python3 -c "
t='((((((((((((((((((((((((((...))))))....)))))))....))))))....)))))))'
n=len(t)
# build sequence
# outer pairs 0-66...6-60 : indices 0..6 pair with 60..66
# indices 7..13 pair with 45..51... wait let me just assign by structure
# Build complementary GC pairs
seq=['A']*n
pairset={}
stack=[]
for i,c in enumerate(t):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairset[j]=i
# assign: alternate G-C for pairs
for i in range(n):
    if t[i]=='(' and i not in pairset:
        pass
# do pairing
k=0
for i in sorted(pairset.keys()):
    if i<pairset[i]:
        if k%2==0:
            seq[i]='G'; seq[pairset[i]]='C'
        else:
            seq[i]='C'; seq[pairset[i]]='G'
        k+=1
# unpaired -> A
for i,c in enumerate(t):
    if c=='.':
        seq[i]='A'
print(''.join(seq))
print(len(''.join(seq)))
"

